window.phosphobot_url = String(url).replace(/\/$/, "");
try { this.variables.setVar("phosphobot_url", window.phosphobot_url); } catch (e) {}
return "";

function base(ctx) {
  try { return String(ctx.variables.getVar("phosphobot_url") || window.phosphobot_url || "http://192.168.100.103:8021").replace(/\/$/, ""); }
  catch (e) { return String(window.phosphobot_url || "http://192.168.100.103:8021").replace(/\/$/, ""); }
}
var rid = Math.max(1, parseInt(robot, 10) || 1) - 1;
var idx = Math.max(1, parseInt(joint, 10) || 1) - 1;
var xhr = new XMLHttpRequest();
xhr.open("POST", base(this) + "/joints/read?robot_id=" + rid, false);
xhr.setRequestHeader("Content-Type", "application/json");
xhr.send(JSON.stringify({source: "robot", unit: "degrees"}));
if (xhr.status < 200 || xhr.status >= 300) { throw new Error("/joints/read HTTP " + xhr.status + ": " + xhr.responseText); }
var data = JSON.parse(xhr.responseText || "{}");
var angle = data.angles ? data.angles[idx] : null;
try { this.variables.setVar("current_angle", angle); } catch (e) {}
return angle;

