try { this.variables.setVar("last_response", xhr.responseText || "{}"); } catch (e) {}
return data.robot_status ? data.robot_status.length : ((data.robots || []).length);

function base(ctx) {
  try { return String(ctx.variables.getVar("phosphobot_url") || window.phosphobot_url || "http://192.168.100.103:8021").replace(/\/$/, ""); }
  catch (e) { return String(window.phosphobot_url || "http://192.168.100.103:8021").replace(/\/$/, ""); }
}
function deg2mu(d) { return d * 4096 / 360 + 2048; }
var rid = Math.max(1, parseInt(robot, 10) || 1) - 1;
var id = Math.max(1, parseInt(joint, 10) || 1);
var target = Number(angle);
var xhr = new XMLHttpRequest();
xhr.open("POST", base(this) + "/joints/write?robot_id=" + rid, false);
xhr.setRequestHeader("Content-Type", "application/json");
xhr.send(JSON.stringify({joints_ids: [id], angles: [deg2mu(target)], unit: "motor_units"}));
if (xhr.status < 200 || xhr.status >= 300) { throw new Error("/joints/write HTTP " + xhr.status + ": " + xhr.responseText); }
try {
  this.variables.setVar("target_angle", target);
  this.variables.setVar("last_response", xhr.responseText || "{}");
} catch (e) {}
return "";

window.pid_p = Number(p);
window.pid_i = Number(i);
window.pid_d = Number(d);
window.pid_integral = 0;
window.pid_last_error = 0;
try {
  this.variables.setVar("pid_p", window.pid_p);
  this.variables.setVar("pid_i", window.pid_i);
  this.variables.setVar("pid_d", window.pid_d);
  this.variables.setVar("pid_integral", 0);
  this.variables.setVar("pid_error", 0);
  this.variables.setVar("pid_derivative", 0);
} catch (e) {}
return "";

function getNum(ctx, name, fallback) {
  try { var v = ctx.variables.getVar(name); return Number(v == null || v === "" ? fallback : v); }
  catch (e) { return Number(window[name] == null ? fallback : window[name]); }
}
var p = getNum(this, "pid_p", 1);
var i = getNum(this, "pid_i", 0);
var d = getNum(this, "pid_d", 0);
var step = Math.max(0.001, Number(dt) || 0.1);
var error = Number(target) - Number(current);
window.pid_integral = Number(window.pid_integral || 0) + error * step;
var derivative = (error - Number(window.pid_last_error || 0)) / step;
window.pid_last_error = error;
var output = p * error + i * window.pid_integral + d * derivative;
try {
  this.variables.setVar("pid_error", error);
  this.variables.setVar("pid_integral", window.pid_integral);
  this.variables.setVar("pid_derivative", derivative);
} catch (e) {}
return output;

function base(ctx) {
  try { return String(ctx.variables.getVar("phosphobot_url") || window.phosphobot_url || "http://192.168.100.103:8021").replace(/\/$/, ""); }
  catch (e) { return String(window.phosphobot_url || "http://192.168.100.103:8021").replace(/\/$/, ""); }
}
function post(ctx, path, body) {
  var xhr = new XMLHttpRequest();
  xhr.open("POST", base(ctx) + path, false);
  xhr.setRequestHeader("Content-Type", "application/json");
  xhr.send(JSON.stringify(body || {}));
  if (xhr.status < 200 || xhr.status >= 300) { throw new Error(path + " HTTP " + xhr.status + ": " + xhr.responseText); }
  return JSON.parse(xhr.responseText || "{}");
}
function getNum(ctx, name, fallback) {
  try { var v = ctx.variables.getVar(name); return Number(v == null || v === "" ? fallback : v); }
  catch (e) { return Number(window[name] == null ? fallback : window[name]); }
}
function deg2mu(d) { return d * 4096 / 360 + 2048; }
var rid = Math.max(1, parseInt(robot, 10) || 1) - 1;
var id = Math.max(1, parseInt(joint, 10) || 1);
var idx = id - 1;
var read = post(this, "/joints/read?robot_id=" + rid, {source: "robot", unit: "degrees"});
var current = Number(read.angles ? read.angles[idx] : 0);
var step = Math.max(0.001, Number(dt) || 0.1);
var error = Number(target) - current;
var p = getNum(this, "pid_p", 1);
var i = getNum(this, "pid_i", 0);
var d = getNum(this, "pid_d", 0);
window.pid_integral = Number(window.pid_integral || 0) + error * step;
var derivative = (error - Number(window.pid_last_error || 0)) / step;
window.pid_last_error = error;
var output = p * error + i * window.pid_integral + d * derivative;
var next = current + output;
var result = post(this, "/joints/write?robot_id=" + rid, {joints_ids: [id], angles: [deg2mu(next)], unit: "motor_units"});
try {
  this.variables.setVar("current_angle", current);
  this.variables.setVar("target_angle", Number(target));
  this.variables.setVar("pid_error", error);
  this.variables.setVar("pid_integral", window.pid_integral);
  this.variables.setVar("pid_derivative", derivative);
  this.variables.setVar("last_response", JSON.stringify(result));
} catch (e) {}
return "";

